export const evolutionTrends = [
  { number:'01', title:'Reconstruction → grounded generation', summary:'Generative priors now complete occluded surfaces, missing views, appearance, and digital cousins. The emerging rule is to preserve provenance: observed evidence and imagined completion should remain distinguishable.', signal:'Generation proposes; geometry and evidence correct.', refs:[{label:'Lucida',href:'https://arxiv.org/html/2608.30821'}] },
  { number:'02', title:'VLM annotator → pipeline controller', summary:'VLMs are moving beyond one-shot labels and parameter guesses. They select frames and entities, route specialist tools, inspect intermediate artifacts, issue structured edits, and decide when a refinement loop should stop.', signal:'Reasoning becomes tool use over visible artifacts.', refs:[{label:'Agentic Real2Sim',href:'https://arxiv.org/html/2607.19190'},{label:'Lucida / GizmoAct',href:'https://arxiv.org/html/2608.30821#S2.SS3'}] },
  { number:'03', title:'Monolithic reconstruction → composable contract', summary:'A scene is increasingly represented as persistent objects, relations, editable assets, temporal state, physics, and validation traces—not only one mesh, splat, or radiance field.', signal:'Scene graphs and episode twins become system interfaces.', refs:[{label:'Agentic Real2Sim',href:'https://arxiv.org/html/2607.19190#S3'}] },
  { number:'04', title:'One simulator → two converging branches', summary:'Explicit simulators expose state, contacts, forces, resets, and numerical dynamics. Generative simulators predict future observations or latent state. Hybrid systems try to bind learned rendering and change to persistent 3D state.', signal:'The key test is intervention, not visual realism.', refs:[{label:'EgoSim',href:'https://egosimulator.github.io/'},{label:'World Labs Atlas',href:'https://www.worldlabs.ai/blog/atlas'}] },
  { number:'05', title:'Demonstration → task interface', summary:'Human video is no longer only a trajectory source. It can identify an object, demonstrate an unfamiliar interaction, specify temporal order, or act as an in-context prompt for a pretrained policy.', signal:'Transfer shifts from copying motion to inferring invariants.', refs:[{label:'Zero-WAM',href:'https://robbyant-research.github.io/Zero-WAM/'}] },
  { number:'06', title:'Fixed pipeline → replaceable compiler', summary:'Modern systems increasingly compile raw capture through interchangeable perception, generation, grounding, physics, and policy modules. Better foundation models can improve one stage without redesigning the entire workflow.', signal:'Modularity becomes a research and maintenance strategy.', refs:[{label:'SimFoundry',href:'https://research.nvidia.com/labs/gear/simfoundry/'}] },
  { number:'07', title:'Manual authoring → verification', summary:'Automation reduces mesh and scene labor but moves effort into detecting hallucination, checking scale and pose, repairing collision geometry, validating articulation, identifying dynamics, and measuring sim–real policy correlation.', signal:'The bottleneck moves; it does not disappear.', refs:[{label:'SimFoundry',href:'https://research.nvidia.com/labs/gear/simfoundry/'},{label:'Agentic Real2Sim',href:'https://arxiv.org/html/2607.19190'}] },
  { number:'08', title:'Static Gaussian twin → causal 4D world', summary:'Robot learning first adopted 3DGS as a photoreal observation layer synchronized with conventional physics. Newer systems add animated Gaussian agents or time-varying scenes; SoMA now demonstrates robot-action-conditioned Gaussian dynamics for deformables, while broad causal interaction and policy-training evidence remain early.', signal:'A time-indexed scene replays motion; a simulator must answer what a new action changes.', refs:[{label:'SoMA',href:'https://city-super.github.io/SoMA/'},{label:'ReaDy-Go',href:'https://syeon-yoo.github.io/ready-go-site/'},{label:'Physics-driven editable 4DGS',href:'https://arxiv.org/abs/2605.13591'},{label:'Kinema4D',href:'https://mutianxu.github.io/Kinema4D-project-page/'},{label:'GaussGym',href:'https://gauss-gym.com/'}] },
];

