export const rlRoles: RLRole[] = [
  { number:'01', title:'Feasibility oracle', where:'After kinematic retargeting; before dataset acceptance', role:'A privileged imitation policy tests whether the target body can actually track a reference under contact, balance, torque, and joint constraints. Failed rollouts become a data filter rather than poisoned supervision.', signal:'Reward exposes executable motion—not merely low IK error.', evidence:'H2O filters roughly 10k retargeted AMASS motions to about 8.5k trackable motions with a privileged RL imitator before training its deployable tracker.', refs:[{label:'H2O',href:'https://arxiv.org/abs/2403.04436'}] },
  { number:'02', title:'Dynamics-aware motion adapter', where:'Between human reference motion and robot control', role:'Physics-based RL converts a pose or contact reference into a feedback policy that can recover from perturbations. It resolves the part that frame-wise IK cannot: how to move through dynamics.', signal:'Reference motion supplies intent; interaction supplies robustness.', evidence:'DeepMimic established reward-guided physical imitation; H2O uses a separate observation-constrained PPO tracker for zero-shot execution on the humanoid.', refs:[{label:'DeepMimic',href:'https://xbpeng.github.io/projects/DeepMimic/'},{label:'H2O',href:'https://human2humanoid.com/'}] },
  { number:'03', title:'Scene-authoring policy', where:'Inside the real2sim compiler itself', role:'RL can optimize a perception–action loop over editable scene state. The action is no longer a motor command: it may be a rotation, translation, scale edit, tool call, or stop decision.', signal:'The reconstructed world becomes the RL environment.', evidence:'Lucida fine-tunes GizmoAct after SFT; on its hard subset RL reduces rotation error to 20.98° from 45.19° for SFT and keeps correcting residual errors instead of stopping early.', refs:[{label:'Lucida / GizmoAct',href:'https://arxiv.org/html/2608.30821#S2.SS3.SSS5'}] },
  { number:'04', title:'Policy learner and simulator consumer', where:'After state, actions, transitions, resets, and rewards exist', role:'RL turns a reconstructed environment into counterfactual experience: explore failures, practice contact-rich behavior, and optimize beyond a finite demonstration set.', signal:'This is the familiar role—but it depends on every upstream contract.', evidence:'RialTo trains task policies in a reconstructed digital twin; GaussGym couples parallel physics with Gaussian rendering for high-throughput pixel-based RL.', refs:[{label:'RialTo',href:'https://real-to-sim-to-real.github.io/RialTo/'},{label:'GaussGym',href:'https://gauss-gym.com/'}] },
  { number:'05', title:'Reality-gap repair', where:'After an initial policy touches the real robot', role:'Real rollout residuals can train a corrective model, which is inserted back into simulation before another round of RL. This makes real2sim2real a calibration loop rather than a one-shot export.', signal:'Reality supplies the residual; simulation supplies safe iteration.', evidence:'ASAP learns a delta action model from real Unitree G1 trajectories, integrates it into the simulator, and fine-tunes the pretrained motion policy against the aligned dynamics.', refs:[{label:'ASAP',href:'https://arxiv.org/abs/2502.01143'}] },
  { number:'06', title:'Fidelity stress test', where:'Across reconstruction, training, and evaluation', role:'Policy optimization amplifies simulator shortcuts. Divergent behavior, wrong policy ranking, or brittle transfer reveals which geometry, sensing, contact, or dynamics details were decision-critical.', signal:'RL operationalizes fidelity; it does not manufacture truth.', evidence:'SimFoundry evaluates sim–real policy correlation rather than relying on render quality alone; this is the right audit for a simulator meant to support policy decisions.', refs:[{label:'SimFoundry',href:'https://research.nvidia.com/labs/gear/simfoundry/'}] },
];

