export const efficiencyDimensions = [
  { number:'01', metric:'Conversion throughput', definition:'Successful scenes or assets per operator-hour and GPU-hour.', unit:'scene / h · object / h' },
  { number:'02', metric:'Conversion yield', definition:'Captures that become stable, executable, task-valid simulation artifacts.', unit:'accepted / attempted' },
  { number:'03', metric:'Data throughput', definition:'Successful, unique trajectories under stated hardware and filtering.', unit:'trajectory / GPU-day' },
  { number:'04', metric:'Reuse multiplier', definition:'Tasks, layouts, embodiments, or policy checkpoints served by each scene.', unit:'uses / scene' },
  { number:'05', metric:'Policy efficiency', definition:'Held-out real success improvement for a fixed synthetic-data budget.', unit:'Δ success / 1K trajectories' },
  { number:'06', metric:'Real-data equivalent', definition:'Real demonstrations required to match the synthetic mixture’s value.', unit:'real-demo equivalent' },
  { number:'07', metric:'Evaluation efficiency', definition:'Physical trials avoided while preserving policy rank and failures.', unit:'r · MMRV · trials avoided' },
  { number:'08', metric:'Total cost', definition:'Capture, correction, compute, storage, authoring, and hardware validation.', unit:'operator-h · GPU-h · $' },
];

export const realityAlignmentLevels = [
  { number:'01', level:'Visual', check:'Do real and simulated sensor observations agree?', metrics:'PSNR · SSIM · LPIPS · feature / color error', risk:'Good images can hide wrong geometry or physics.' },
  { number:'02', level:'Geometry', check:'Are camera, scale, surfaces, objects, and articulation aligned?', metrics:'Chamfer · F-score · pose ADD · joint-axis error', risk:'Static agreement does not prove stable interaction.' },
  { number:'03', level:'Physical', check:'Are contacts, support, collision, mass, friction, and deformation plausible?', metrics:'penetration · stability · parameter error · replay success', risk:'A stable scene may still produce the wrong behavior.' },
  { number:'04', level:'Behavioral', check:'Does the same action produce comparable motion and task progress?', metrics:'trajectory distance · contact sequence · object-state error', risk:'One replay can pass while a policy fails under perturbation.' },
  { number:'05', level:'Policy ranking', check:'Does simulation preserve which checkpoint or method is better?', metrics:'Pearson / Spearman r · MMRV · failure agreement', risk:'Correlation needs multiple policies, tasks, and confidence intervals.' },
  { number:'06', level:'Hardware outcome', check:'Does training or selection in the twin improve real task success?', metrics:'real success · robustness · unseen-object / scene transfer', risk:'Strongest evidence, but expensive and often statistically small.' },
];

export const simulationOpenQuestions = [
  { number:'01', title:'Training value', question:'Which synthetic variation changes the learned policy?', body:'More trajectories help only when they add task, state, contact, viewpoint, or embodiment coverage the learner can use. Raw episode count is a weak proxy for effective diversity.' },
  { number:'02', title:'Evaluation validity', question:'Does simulator success predict hardware success?', body:'A benchmark is valuable when it preserves rankings, failure modes, and intervention effects—not merely when it looks realistic. This requires paired real tests and confidence intervals.' },
  { number:'03', title:'Leakage & tuning', question:'Is the test world truly held out?', body:'Open assets and reusable scenes invite repeated tuning. Hidden seeds, private scenarios, versioned engines, and strict train/test asset isolation matter as much as the headline score.' },
  { number:'04', title:'Embodiment coverage', question:'What transfers across robot bodies?', body:'The same task label can hide different reachability, sensing, grippers, control rates, and action spaces. Cross-embodiment evaluation needs an explicit invariant, not just converted joint vectors.' },
  { number:'05', title:'Physics budget', question:'Where is fidelity worth the compute?', body:'Rigid placement, cloth folding, liquids, tactile contact, and locomotion need different solvers. Selective fidelity may beat uniformly expensive simulation if error is measured at the policy boundary.' },
  { number:'06', title:'Data accounting', question:'What is one synthetic hour worth?', body:'Hours, frames, and episodes should be reported with uniqueness, generator success, filtering, reset cost, compute, and real-data equivalents. Otherwise scale claims are difficult to compare.' },
];

