export type GlossaryTerm = {
  term: string;
  definition: string;
  distinction: string;
  refs: { label: string; href: string }[];
};

export const glossary: GlossaryTerm[] = [
  { term:'Learning from Demonstration (LfD)', definition:'A broad robot-teaching paradigm in which demonstrations, corrections, or teacher feedback help derive a policy.', distinction:'Broader than behavior cloning; the teacher may be a human, another robot, a planner, or a simulator.', refs:[{label:'Argall et al. · 2009',href:'https://www.cs.cmu.edu/~mmv/papers/09ras-survey.pdf'}] },
  { term:'Imitation learning', definition:'The umbrella problem of learning behavior that reproduces selected properties of an expert.', distinction:'The target may be actions, occupancy, style, reward, motion, or task outcome—not necessarily frame-by-frame copying.', refs:[{label:'Schaal · 1999',href:'https://pubmed.ncbi.nlm.nih.gov/10354577/'},{label:'DeepMimic · 2018',href:'https://xbpeng.github.io/projects/DeepMimic/'}] },
  { term:'Behavior cloning (BC)', definition:'Supervised learning of a policy from paired observations and expert actions, usually minimizing action prediction error.', distinction:'Simple and scalable, but errors compound when the learned policy visits states absent from the demonstrations.', refs:[{label:'LfD survey · 2009',href:'https://www.cs.cmu.edu/~mmv/papers/09ras-survey.pdf'},{label:'Diffusion Policy · 2023',href:'https://diffusion-policy.cs.columbia.edu/'}] },
  { term:'Retargeting', definition:'Adapting a source motion or interaction to a target body while preserving chosen task, pose, contact, or style constraints.', distinction:'Can be pure kinematics, constrained optimization, physics-based control, or learned correspondence; it need not learn a policy.', refs:[{label:'Gleicher · 1998',href:'https://graphics.cs.wisc.edu/Papers/1998/Gle98/'},{label:'UMR · 2026',href:'https://arxiv.org/abs/2609.02134'}] },
  { term:'One-shot learning', definition:'Acquiring or adapting a skill from one demonstration or example after prior learning across tasks.', distinction:'“One-shot” describes the adaptation-data count. It does not automatically mean no parameter updates, and it is not the same as single-view reconstruction.', refs:[{label:'Finn et al. · 2017',href:'https://proceedings.mlr.press/v78/finn17a.html'}] },
  { term:'In-context learning (ICL)', definition:'Conditioning a pretrained policy on demonstrations at inference time so it performs a new task without updating model parameters.', distinction:'A demonstration is part of the model input/context, not a fine-tuning dataset. One or many examples can be placed in context.', refs:[{label:'ICRT · 2024',href:'https://icrt.dev/'}] },
  { term:'Physical prompting', definition:'A recent label for placing sensorimotor demonstrations—observations plus action trajectories—inside a robot model’s context window.', distinction:'Coined in the GEN-1.5 research report; it is an emerging usage, not yet a settled community-wide technical category.', refs:[{label:'GEN-1.5 · 2026',href:'https://generalistai.com/blog/gen-1.5'}] },
  { term:'Zero-shot transfer', definition:'Applying a trained system to a new task, scene, object, or deployment domain without target-specific examples or updates.', distinction:'Always ask what is zero-shot: the task, object, embodiment, scene, or real-world domain. “Zero-shot sim-to-real” is narrower.', refs:[{label:'OpenAI domain randomization · 2017',href:'https://openai.com/index/robots-that-learn/'}] },
  { term:'Cross-embodiment transfer', definition:'Moving task or motion information across bodies with different kinematics, action spaces, sensors, or end effectors.', distinction:'It may transfer high-level intent, latent features, end-effector paths, or full-body motion; these are not equivalent claims.', refs:[{label:'AnyTeleop · 2023',href:'https://yzqin.github.io/anyteleop/'},{label:'SPIDER · 2025/26',href:'https://github.com/facebookresearch/spider'}] },
  { term:'Video-to-robot learning', definition:'Using human or robot video to improve robot perception, task understanding, action inference, data generation, or policy learning.', distinction:'Not every method reconstructs a simulator or recovers actions. Task-, observation-, and action-oriented routes carry different information.', refs:[{label:'Human-video survey · 2026',href:'https://arxiv.org/abs/2604.27621'}] },
  { term:'Real-to-sim', definition:'Recovering reusable scene, asset, appearance, physics, calibration, or trajectory state from real observations.', distinction:'A photorealistic renderer is not automatically a physically valid simulator; a retargeted trajectory is not automatically a persistent world model.', refs:[{label:'Scalable Real2Sim · 2025',href:'https://scalable-real2sim.github.io/'},{label:'SimFoundry · 2026',href:'https://research.nvidia.com/labs/gear/simfoundry/'}] },
  { term:'Scene graph / structured world state', definition:'A persistent graph of entities and typed relations that binds semantic identity to spatial, temporal, physical, functional, or task-relevant evidence.', distinction:'It is not a mesh, mask collection, caption, or simulator by itself. Its value is the explicit interface it provides between perception, asset authoring, simulation, planning, and policy.', refs:[{label:'Hydra · 2022',href:'https://github.com/MIT-SPARK/Hydra'},{label:'ConceptGraphs · 2023/24',href:'https://github.com/concept-graphs/concept-graphs'},{label:'Lucida · 2026',href:'https://arxiv.org/html/2608.30821#S2.SS1'}] },
  { term:'Generative simulator / neural world model', definition:'A learned transition model that predicts future observations or world state conditioned on actions, context, or trajectories.', distinction:'Video synthesis can create training examples without being a simulator. Ask whether actions cause a persistent, queryable state transition and whether counterfactual rollouts are validated.', refs:[{label:'EgoSim · 2026',href:'https://egosimulator.github.io/'},{label:'World Models · 2018',href:'https://worldmodels.github.io/'}] },
  { term:'World–action model', definition:'A model that jointly predicts future visual evolution and robot actions, allowing imagined video and control to share one causal representation.', distinction:'The “world” may be an internal policy latent rather than an external environment that another policy can step, reset, and inspect.', refs:[{label:'Zero-WAM · 2026',href:'https://robbyant-research.github.io/Zero-WAM/'}] },
  { term:'Foundation model / VLA', definition:'A broadly pretrained model adapted across many tasks; a vision-language-action model directly conditions robot actions on visual and language inputs.', distinction:'“Foundation” concerns pretraining breadth and reuse. It does not by itself imply in-context learning, physical grounding, or open availability.', refs:[{label:'OpenVLA · 2024',href:'https://github.com/openvla/openvla'},{label:'Octo · 2024',href:'https://octo-models.github.io/'}] },
];

